import heapq

def match(orders):
    buy_heap = []   # entries: (-price, seq, id) - max-price priority
    sell_heap = []  # entries: (price, seq, id) - min-price priority
    book = {}       # id -> {'side':..., 'price':..., 'qty':..., 'seq':...}
    trades = []
    seq_counter = 0

    def clean_top(heap):
        while heap:
            price_key, seq, oid = heap[0]
            o = book.get(oid)
            if o is None or o['qty'] <= 0:
                heapq.heappop(heap)
                continue
            return heap[0]
        return None

    for order in orders:
        seq_counter += 1
        typ = order[0]

        if typ == 'cancel':
            oid = order[1]
            if oid in book:
                del book[oid]
            continue

        if typ == 'limit':
            _, oid, side, price, qty = order
        elif typ == 'ioc':
            _, oid, side, price, qty = order
        else:  # market
            _, oid, side, qty = order
            price = None

        remaining = qty
        opp_heap = sell_heap if side == 'buy' else buy_heap

        while remaining > 0:
            top = clean_top(opp_heap)
            if top is None:
                break
            price_key, oseq, oid2 = top
            resting = book[oid2]
            resting_price = resting['price']

            if typ != 'market':
                if side == 'buy' and resting_price > price:
                    break
                if side == 'sell' and resting_price < price:
                    break

            # perform match
            heapq.heappop(opp_heap)
            trade_qty = min(remaining, resting['qty'])
            if side == 'buy':
                trades.append([oid, oid2, resting_price, trade_qty])
            else:
                trades.append([oid2, oid, resting_price, trade_qty])

            remaining -= trade_qty
            resting['qty'] -= trade_qty

            if resting['qty'] > 0:
                heapq.heappush(opp_heap, (price_key, oseq, oid2))
            else:
                if oid2 in book:
                    del book[oid2]

        if typ == 'limit' and remaining > 0:
            book[oid] = {'side': side, 'price': price, 'qty': remaining, 'seq': seq_counter}
            if side == 'buy':
                heapq.heappush(buy_heap, (-price, seq_counter, oid))
            else:
                heapq.heappush(sell_heap, (price, seq_counter, oid))
        # ioc/market remainder discarded (no resting entry)

    return trades

